    it('starts a bound follow-up from A without rerunning it and keeps A and B unchanged', async () => {
        const a = buildA();
        const b = buildB();
        await coldStart([b, a], b);
        const aBefore = JSON.stringify(byId(a.id));
        const bBefore = JSON.stringify(byId(b.id));
