        localStorage.setItem('cvf-executions-storage', JSON.stringify({state:{executions:[a,b],currentExecution:b},version:0}));
        await useExecutionStore.persist.rehydrate();
        const before = JSON.stringify(useExecutionStore.getState().executions);
        const network = vi.spyOn(globalThis, 'fetch');
        const clipboard = vi.fn().mockResolvedValue(undefined);
        Object.defineProperty(navigator, 'clipboard', {value:{writeText:clipboard},configurable:true});
        const history = render(<HistoryPage />);
        click('open-saved-result');
        expect(navigation.pushes).toEqual(['/home?result=local%2FA%26x']);
