        act(() => useExecutionStore.getState().setCurrentExecution(b));
        expect(document.body.textContent).toContain(a.output);
        expect(document.body.textContent).not.toContain(b.output);
        fireEvent.click(screen.getByRole('button', { name: /Export/ }));
        await act(async () => fireEvent.click(screen.getByRole('button', { name: /Copy to Clipboard/ })));
        const copied = String(clipboard.mock.calls[0][0]);
