    it.each(['result=', 'result=%20%20', 'continue=&result=exec_fixture_B', 'continue=%20&result=exec_fixture_B'])(
        'clears a prior A result for explicitly missing selected id: %s', (query) => {
            const a = buildA(); const b = buildB(); seed([a,b], b);
            navigation.params = new URLSearchParams('result=' + a.id);
            const view = render(<HomePage />);
